 private JSONObject status()throws Exception{JSONArray runs=new JSONArray(),operations=new JSONArray();File[]dirs=rawRoot.listFiles();if(dirs!=null){if(dirs.length>32)throw new IOException("RAW96_RUN_COUNT");Arrays.sort(dirs);for(File d:dirs){if(Files.isSymbolicLink(d.toPath())||!d.isDirectory()||!d.getName().matches("s[a-f0-9]{20}"))throw new IOException("RAW96_RUN_PATH");File f=new File(d,"raw.jsonl");runs.put(obj("run",d.getName(),"bytes",f.length()));}}for(FileOps87.Op o:ops.list())operations.put(obj("id",o.id,"phase",o.phase,"sha256",o.sha,"manifestSha256",o.artifactHead,"reason",o.reason));return obj("ok",true,"runs",runs,"operations",operations,"busy",busy,"linkOpen",owner.directOpen96(),"authorityRestorable",false);}
 public synchronized void request(String id,String action,String body){if(io.isShutdown()||io.getQueue().size()>=2){error(id,new IOException("RAW96_QUEUE_BOUND"));return;}if(!fatal.isEmpty()){error(id,new IOException(fatal));return;}if(action.equals("status")){io.execute(()->{try{answer(id,status());}catch(Exception e){error(id,e);}});return;}if(busy||owner.directOpen96()){error(id,new IOException("CLOSE_NATIVE_LINK_BEFORE_RAW_SAF"));return;}busy=true;replyId=id;io.execute(()->{try{JSONObject q=new JSONObject(body);if(action.equals("export"))prepare(id,q);else if(action.equals("reconcile")||action.equals("recover-copy")){String original=q.getString("id");FileOps87.Op op=ops.get(original);if(!op.phase.equals("UNKNOWN")||op.sha.isEmpty())throw new IOException("RAW96_UNKNOWN_ORIGINAL_REQUIRED");byte[]bytes=RawArchive96.read(artifact(original).toPath(),RawArchive96.MAX);if(!DraftStore.hash(bytes).equals(op.sha))throw new IOException("RAW96_STAGE_CHANGED");opId=original;recovery=action.equals("recover-copy");if(recovery)ops.update(original,"PICKER_PENDING",op.sha,"",op.artifactHead,"EXPLICIT_COPY_SAME_BYTES_NOT_NEW_CAPTURE");picker(recovery);}else throw new IOException("RAW96_ACTION");}catch(Exception e){unknown(e);busy=false;opId=null;error(id,e);}});}
 private void prepare(String id,JSONObject q)throws Exception{String run=q.getString("run"),receiver=q.getString("receiver"),nonce=q.getString("nonce");if(!run.matches("s[a-f0-9]{20}")||!receiver.matches("[A-Za-z0-9_-]{3,64}")||!nonce.matches("[A-Za-z0-9_-]{16,96}")||!q.optBoolean("acknowledgeEvidenceOnly"))throw new IOException("RAW96_CONTEXT_CONFIRMATION");File[]old=root.listFiles();long used=0;if(old==null||old.length>=64)throw new IOException("RAW96_STAGE_COUNT_NO_DELETE");for(File f:old){if(Files.isSymbolicLink(f.toPath())||!f.isFile())throw new IOException("RAW96_STAGE_FOREIGN");used+=f.length();}if(used+RawArchive96.MAX>128L*1024*1024||root.getUsableSpace()<DraftStore.RESERVE+2L*RawArchive96.MAX)throw new IOException("RAW96_STAGE_QUOTA_RESERVE");Path original=new File(new File(rawRoot,run),"raw.jsonl").toPath();if(Files.isSymbolicLink(original.getParent()))throw new IOException("RAW96_SOURCE_SYMLINK");byte[]raw=RawArchive96.read(original,RawArchive96.RAW);RawArchive96.Prefix prefix=RawArchive96.replay(raw);JSONObject meta=new JSONObject(new String(prefix.meta,StandardCharsets.UTF_8));if(!meta.getJSONObject("ownedLaunchAssertion").getString("run").equals(run))throw new IOException("RAW96_RUN_META");LinkedHashMap<String,byte[]>files=new LinkedHashMap<>();files.put("raw.jsonl",raw);files.put("source-meta.json",prefix.meta);for(DraftStore.Snapshot s:spaces.sitl().history(null)){JSONObject review=new JSONObject(new String(s.bytes,StandardCharsets.UTF_8));if(run.equals(review.optString("run"))){if(!prefix.head.equals(review.optString("rawHead"))||prefix.records!=review.getInt("rawRecords"))throw new IOException("RAW96_REVIEW_BINDING");files.put("review.json",s.bytes);break;}}JSONObject context=obj("snapshot",id,"run",run,"receiver",receiver,"nonce",nonce,"exporterSourceId",BuildInfo90.SOURCE_ID,"rawSourceId",meta.getString("sourceId"),"captureElapsedMs",SystemClock.elapsedRealtime(),"authorityRestorable",false);String manifest=RawArchive96.manifest(files,context.toString());byte[]zip=RawArchive96.build(files,context.toString());if(owner.directOpen96()||!DraftStore.hash(raw).equals(DraftStore.hash(RawArchive96.read(original,RawArchive96.RAW))))throw new IOException("RAW96_SOURCE_CHANGED");String digest=DraftStore.hash(zip),mh=DraftStore.hash(manifest.getBytes(StandardCharsets.UTF_8));ops.begin(id,"export",spaces.id(),prefix.head,digest);opId=id;RawArchive96.publish(artifact(id).toPath(),zip);JSONObject d=obj("id",id,"bytes",zip.length,"sha256",digest,"manifestSha256",mh,"context",context);RawArchive96.publish(new File(root,id+".json").toPath(),d.toString().getBytes(StandardCharsets.UTF_8));ops.update(id,"PICKER_PENDING",digest,"",mh,"CLOSED_LINK_IMMUTABLE_EVIDENCE_SNAPSHOT_NOT_MISSION_PASS");recovery=false;picker(true);}
 private void picker(boolean create){owner.runOnUiThread(()->{try{if(owner.directOpen96())throw new IOException("RAW96_ACTIVE_LINK");Intent i=new Intent(create?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/zip");if(create)i.putExtra(Intent.EXTRA_TITLE,"AERIS-native96-"+opId+".zip");owner.startActivityForResult(i,create?9601:9602);}catch(Exception e){unknown(e);busy=false;error(replyId,e);}});}
 private void unknown(Exception e){try{if(opId==null)return;FileOps87.Op o=ops.get(opId);if(!Arrays.asList("COMPLETED","CANCELLED").contains(o.phase))ops.update(o.id,"UNKNOWN",o.sha,"",o.artifactHead,"OUTCOME_UNCONFIRMED_RECONCILE_SAME_ORIGINAL_NO_RETRY");}catch(Exception ignored){}}
 public void result(int request,int result,Intent intent){String original=opId,reply=replyId;if(original==null){busy=false;return;}io.execute(()->{try{FileOps87.Op op=ops.get(original);JSONObject d=descriptor(original);if(result!=Activity.RESULT_OK||intent==null||intent.getData()==null){if(request==9601&&!recovery)ops.update(original,"CANCELLED",op.sha,"",op.artifactHead,"PICKER_CANCELLED_STAGE_RETAINED");else unknown(new IOException("RECONCILIATION_CANCELLED"));throw new IOException("RAW96_CANCELLED_NOT_SUCCESS");}Uri uri=intent.getData();if(!"content".equals(uri.getScheme()))throw new IOException("RAW96_SAF_CONTENT");byte[]bytes=RawArchive96.read(artifact(original).toPath(),RawArchive96.MAX);if(bytes.length!=d.getInt("bytes")||!DraftStore.hash(bytes).equals(op.sha)||owner.directOpen96())throw new IOException("RAW96_ORIGINAL_CHANGED_OR_ACTIVE");ops.update(original,"PROCESSING",op.sha,"",op.artifactHead,"");if(request==9601)try(OutputStream out=owner.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("RAW96_PROVIDER_WRITE");out.write(bytes);out.flush();}try(InputStream in=owner.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("RAW96_PROVIDER_READ");BundleIO88.copy(in,null,bytes.length,op.sha);}ops.update(original,"COMPLETED",op.sha,"",op.artifactHead,"PROVIDER_READBACK_VERIFIED_NOT_MISSION_ACCEPTANCE");answer(reply,obj("ok",true,"id",original,"sha256",op.sha,"manifestSha256",op.artifactHead,"bytes",bytes.length,"providerReadback",true,"authorityRestorable",false));}catch(Exception e){unknown(e);error(reply,e);}finally{busy=false;opId=null;replyId=null;}});}
